mapper.sql:
SELECT distinct CI.ID, CI.CREATE_TIME, CI.MODIFY_TIME, CI.REC_VER, CI.LOGIC_DEL, CI.BUILD_IN, CI.NAME, CI.FILE_ID, CI.ICON_PARTITION, CI.REMARK, SO.ORIGINAL_NAME AS FILE_NAME, SO.URL FROM common_icon CI LEFT JOIN sys_oss so on so.id = ci.FILE_ID WHERE 1 = 1 AND CI.LOGIC_DEL = 0
AND CI.ID = #{commonIconDto.id}
AND SO.ID = #{commonIconDto.fileId}
AND CI.NAME LIKE CONCAT('%', #{commonIconDto.name}, '%')
AND CI.ICON_PARTITION = #{commonIconDto.iconPartition}
ORDER BY CI.CREATE_TIME DESC, CI.MODIFY_TIME DESC

mapper.select:
SELECT distinct CI.ID, CI.CREATE_TIME, CI.MODIFY_TIME, CI.REC_VER, CI.LOGIC_DEL, CI.BUILD_IN, CI.NAME, CI.FILE_ID, CI.ICON_PARTITION, CI.REMARK, SO.ORIGINAL_NAME AS FILE_NAME, SO.URL, SDV.VALUE_NAME ICON_PARTITION_NAME FROM common_icon CI LEFT JOIN sys_oss so on so.id = ci.FILE_ID LEFT JOIN sys_dict_value SDV ON SDV.DICT_KEY = 'COMMON_ICON_PARTITION' AND CI.ICON_PARTITION = SDV.VALUE WHERE 1 = 1 AND CI.LOGIC_DEL = 0
AND CI.ID = #{commonIconDto.id}
AND SO.ID = #{commonIconDto.fileId}
AND CI.NAME LIKE CONCAT('%', #{commonIconDto.name}, '%')
AND CI.ICON_PARTITION = #{commonIconDto.iconPartition}
GROUP BY CI.ICON_PARTITION, CI.NAME, CI.ORDER_NUM ORDER BY CI.ICON_PARTITION, CI.NAME, CI.ORDER_NUM
